SELECT

FROM article a
LEFT JOIN `user` u ON u.id = a.user_id AND u.deleted = 0
LEFT JOIN category c ON c.id = a.category_id AND c.deleted = 0
WHERE a.deleted = 0

    AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.summary LIKE CONCAT('%', #{keyword}, '%'))


    AND a.category_id = #{categoryId}


    AND EXISTS (SELECT 1 FROM article_tag at WHERE at.article_id = a.id AND at.tag_id = #{tagId})


    AND a.status = #{status}


    AND a.user_id = #{authorId}

ORDER BY a.create_time DESC, a.id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM article a
WHERE a.deleted = 0

    AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.summary LIKE CONCAT('%', #{keyword}, '%'))


    AND a.category_id = #{categoryId}


    AND EXISTS (SELECT 1 FROM article_tag at WHERE at.article_id = a.id AND at.tag_id = #{tagId})


    AND a.status = #{status}


    AND a.user_id = #{authorId}

SELECT id, user_id, title, like_count,deleted
FROM article
WHERE id = #{id}

mapper.update:
UPDATE article
SET like_count = like_count+1
WHERE id = #{id}

UPDATE article
SET like_count = GREATEST(like_count-1,0)
WHERE id = #{id}

UPDATE article
SET deleted     = 1,
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

UPDATE article
SET like_count = CASE WHEN like_count > 0 THEN like_count - 1 ELSE 0 END
WHERE id = #{id}
